import SwiftUI
struct CardView:View {
 @EnvironmentObject var store:AppStore
 var body:some View{ScrollView{VStack(alignment:.leading,spacing:18){Text("YOUR READ. YOUR CARD.").font(.caption.weight(.bold)).foregroundStyle(.secondary);Text("Build your fight night.").font(.largeTitle.bold());if !store.events.isEmpty{Picker("Event",selection:Binding(get:{store.event?.id ?? ""},set:{id in store.run{try await store.selectEvent(id)}})){ForEach(store.events){Text($0.name).tag($0.id)}}.pickerStyle(.menu)}
 if let e=store.event{Text(e.venue ?? "").font(.caption).foregroundStyle(.secondary);ForEach(["Main Card","Prelims","Early Prelims","Fight card"],id:\.self){segment in let fights=e.fights.filter{$0.segment==segment};if !fights.isEmpty{Text(segment.uppercased()).font(.caption.bold()).foregroundStyle(.secondary).padding(.top,8);ForEach(fights){FightRow(fight:$0)}}};Text("Photos and card: ESPN / UFC. Missing prices stay unpriced. Refreshed when loaded; pull to refresh.").font(.caption2).foregroundStyle(.secondary)}else{ContentUnavailableView("Loading fight cards",systemImage:"figure.boxing",description:Text("Live cards will appear here when the feed responds."));Button("Retry"){Task{await store.start()}}}}.padding()}.refreshable{await store.start()}.navigationTitle("OnlyFights").navigationBarTitleDisplayMode(.inline).safeAreaInset(edge:.bottom){VStack(spacing:10){HStack{Text("\(store.picks.values.count) picks").font(.subheadline.bold());Spacer();Button("Load saved"){store.run{try await store.loadCloud()}};Button("Save"){store.run{try await store.saveCloud()}}};HStack{Button("Poster",systemImage:"square.and.arrow.up"){store.showPoster=true}.buttonStyle(.bordered).disabled(store.picks.values.isEmpty);Button{store.run{try await store.createParlays()}}label:{Text(store.busy ? "Building…":"Create parlays").frame(maxWidth:.infinity)}.buttonStyle(.borderedProminent).disabled(store.picks.values.count<2||store.busy)}}.padding().background(.ultraThinMaterial)}}
}
struct FightRow:View {
 @EnvironmentObject var store:AppStore;var fight:Fight;@Environment(\.accessibilityReduceMotion) private var reduceMotion
 var selected:FightPick?{store.picks.values[fight.id]}
 var body:some View{VStack(spacing:0){Text(fight.weightclass.uppercased()).font(.caption2.weight(.semibold)).foregroundStyle(.secondary).padding(.top,10);HStack(spacing:2){ForEach(Array(fight.fighters.enumerated()),id:\.element.id){index,a in VStack(spacing:5){Button{withAnimation(reduceMotion ? nil:.easeInOut(duration:0.2)){store.choose(fight,a)}}label:{VStack(spacing:0){AsyncImage(url:a.photo.flatMap(URL.init(string:))){image in image.resizable().scaledToFit()}placeholder:{Image(systemName:"person.fill").resizable().scaledToFit().padding(25).foregroundStyle(.secondary)}.frame(height:122).frame(maxWidth:.infinity);Text(a.name).font(.headline).lineLimit(2).minimumScaleFactor(0.8).frame(minHeight:44);Text(americanOdds(decimalOdds(fight.quote?.fighters[a.id]?.ml))).font(.subheadline.monospacedDigit().bold()).foregroundStyle(selected?.athleteId==a.id ? Color.accentColor:.primary)}.padding(.bottom,8).frame(maxWidth:.infinity).background(selected?.athleteId==a.id ? Color.accentColor.opacity(0.12):Color.clear).contentShape(Rectangle())}.buttonStyle(.plain).accessibilityLabel("\(a.name), \(selected?.athleteId==a.id ? "selected, tap to remove":"tap to pick")");if selected?.athleteId==a.id{Button{store.picks.toggleLock(fight.id);store.persistLocal()}label:{Label(selected?.lock==true ? "Your lock":"Mark lock",systemImage:selected?.lock==true ? "lock.fill":"lock.open")}.font(.caption).foregroundStyle(selected?.lock==true ? .yellow:.secondary)}}.frame(maxWidth:.infinity)}}
 if let p=selected{HStack(alignment:.top,spacing:12){ScrollView(.horizontal,showsIndicators:false){HStack(spacing:8){ForEach(["KO / TKO","Submission","Decision"],id:\.self){method in Button{withAnimation(reduceMotion ? nil:.easeInOut(duration:0.2)){store.picks.method(p.method==method ? nil:method,for:fight.id);store.persistLocal()}}label:{VStack{Text(method=="KO / TKO" ? "KO/TKO":method).font(.caption.bold());Text(americanOdds(decimalOdds(fight.quote?.fighters[p.athleteId]?.methods?[method] ?? nil))).font(.caption2)}}.buttonStyle(.bordered).tint(p.method==method ? Color.accentColor:.gray)}}}.transition(.move(edge:p.athleteId==fight.fighters.first?.id ? .leading:.trailing));if let method=p.method,method != "Decision"{ScrollView(.horizontal,showsIndicators:false){HStack{ForEach(1...fight.rounds,id:\.self){r in Button("R\(r)"){store.picks.round(p.round==r ? nil:r,for:fight.id,maximum:fight.rounds);store.persistLocal()}.buttonStyle(.bordered).tint(p.round==r ? Color.accentColor:.gray)}}}.frame(maxWidth:125).transition(.move(edge:p.athleteId==fight.fighters.first?.id ? .leading:.trailing))}}.padding(10);if p.round != nil{Text("Round pick saved. Exact round odds are not available from this feed.").font(.caption2).foregroundStyle(.secondary).padding(.horizontal)}}
 if let q=fight.quote{Text(q.source+" · "+String(q.checkedAt.prefix(16))).font(.system(size:9)).foregroundStyle(.secondary).padding(8)}}.background(Color.white.opacity(0.035),in:RoundedRectangle(cornerRadius:18)).overlay(RoundedRectangle(cornerRadius:18).stroke(selected==nil ? Color.white.opacity(0.08):Color.accentColor.opacity(0.45)))}
}
